# -*- coding: utf-8 -*-
EXTRA3 = {
    "sixiang-zhongyong": """中庸并非教人折中妥协，而是强调在情感未发与已发之间把握恰好的分寸，所谓“致中和”。宋儒朱熹将其列入四书，使它成为后世士人修身立本的根基；东亚礼文化与日常处世之道，也多受“时中”智慧的浸润。其实“中”更含动态意味，随事而处其宜，不偏不倚而从容中道，至今仍启人深思。""",
    "sixiang-mengzi": """孟子倡“性善”之说，以为恻隐、羞恶、辞让、是非四端乃人皆有之的良知良能。他游说诸侯以王道仁政，留下“富贵不能淫，贫贱不能移”的浩然之气。其民本思想“民为贵，社稷次之，君为轻”更开后世重民论的先声。其“养气”之说与“大丈夫”人格，陶冶了历代读书人的风骨，连帝王亦以仁政自励，影响直贯两千年政治伦理。""",
    "sixiang-zhuangzi": """庄子以“逍遥游”破除以功名利禄为尺度的世俗评判，主张与物委蛇、乘物以游心。那场栩栩然的蝴蝶之梦，道出物我界限的虚幻。其齐物之论不仅慰藉了乱世文心，更渗入中国诗画与山水审美的深处。其“无用之用”“庖丁解牛”等寓言，把哲理化为可感的生活智慧，至今仍为困顿者提供精神的喘息之地。""",
    "classic-daodejing": """《道德经》五千余言分八十一章，以“道法自然”“无为而无不为”为核，言简意远。它不但是道家根源，更被译为多种文字，其“上善若水”“柔弱胜刚强”的智慧跨越时空，成为西方读者最常接触的中国哲思之一。当代管理学与生态学亦从中汲取“无为而治”“知止不殆”的启示，证明其远未过时。""",
    "classic-daxue": """《大学》原为《礼记》一篇，经宋儒表彰而为四书之始。它开宗明义提出“明明德、亲民、止于至善”三纲领，及格物致知、诚正修齐治平八条目，把个人修养与天下秩序连成一气，奠定后世儒者进德修业的总纲目。清代学者焦循谓“大学格物之义，千古聚讼”，足见其诠释空间之大。""",
    "sixiang-yinyang": """阴阳并非善恶对立，而是宇宙中两股相生相成、互为消长的力量，配以五行生克便成古人解释天象、医理与人事的基本框架。从历法节候到中医藏象，这套思维渗透于传统生活的深处，至今仍是理解华夏宇宙观的一把钥匙。它更塑造了国人“物极必反”“祸福相依”的辩证思维习惯。""",
    "sixiang-xunzi": """荀子独倡“人之性恶，其善者伪也”，以为礼法教化方能化性起伪。他隆礼重学，培育出韩非、李斯两位法家巨子，亦以“制天命而用之”的素朴精神，在先秦诸子中别开一格，对汉代礼制影响深远。其《劝学》“锲而不舍，金石可镂”之训，至今仍为学子所诵。""",
    "sixiang-fajia": """法家集商鞅之“法”、申不害之“术”、慎到之“势”而成，至韩非融会贯通。它主张不别亲疏、一断于法，以赏罚二柄驱动耕战，助秦一统。其重制度、尚功效的取向，沉淀为中国两千年君主专制的重要治理资源。然严刑峻法亦致秦祚短促，后世遂倡“外儒内法”以济之。""",
    "sixiang-xinxue": """王阳明龙场悟道后倡“心即理”与“知行合一”，晚年揭“致良知”三字，以为是非只在此心。他讲学不立门户，士农工商皆可成圣，极大解放了道德主体的自信，并东传日本，成为明治志士变革的精神资粮。其“满街尧舜”的平等气象，至今仍叩问行善者本心。""",
    "sixiang-xuanxue": """魏晋玄学祖述《老》《庄》《易》，以“有无”“本末”为辩题，名士清谈析理。王弼贵无、郭象适性，在乱世中为人寻一份超脱。它调和儒道，既释经又谈玄，深刻塑造了当时风度与后世士大夫的精神世界。其“言意之辨”更启发文论与禅思，嵇康《声无哀乐论》即承此理。""",
    "sixiang-dongzhongshu": """董仲舒上《天人三策》，倡“罢黜百家，独尊儒术”，并建构天人感应、阴阳灾异之说，使儒学官学化。他倡大一统、兴太学、立察举，为汉代乃至其后两千年政教格局奠定基调，儒生由此步入权力中枢。其“春秋决狱”“三纲五常”之说则争议至今未息。""",
    "sixiang-yijing": """《周易》以八卦相重而成六十四卦，借阴阳爻变推演吉凶。经孔子及其后学作“十翼”阐发，由卜筮之书升为义理经典。其“穷则变，变则通”的生生之旨，成为国人应对变局、理解盛衰循环的根本智慧。从京房纳甲到邵雍先天图，历代推演不已，影响遍于医、兵、艺。""",
    "mingjia": """名家专辨名实，惠施历物之意、公孙龙“白马非马”之辩，皆极尽逻辑之巧。他们以诡辞挑战常识，虽被讥为“坚白同异”之察，却在中国思想中独留一份对语言与概念边界的清醒反思，惜其学后世几近中绝。近代中西交汇，其思又被重估，与形式逻辑遥相呼应。""",
    "jingxue": """经学即诠解儒家经典的学问，自汉立五经博士、分今古文之争，至郑玄遍注群经而一变。唐修义疏、宋倡义理、清尚考据，历代治经之法迭更，却始终是王朝立政与士人进身之本，堪称传统学术的主脉。皮锡瑞谓“经学盛衰当以时代判之”，信然。""",
    "shixue": """实学重在经世致用，反对空谈心性。明清之际顾炎武、黄宗羲、王夫之痛矫晚明虚浮，倡博学于文、质测之学；清代考据亦以实证为归。这条“崇实黜虚”的脉络，实为传统学术向近代科学精神过渡的桥梁。颜元习斋倡“习行”，其务实已近实科教育气息。""",
    "lishi-han": """汉承秦制而文景休养生息，武帝外攘四夷、内兴太学，国势鼎盛。丝绸之路自此开通，汉字、汉礼、汉律影响深远，“汉族”“汉字”之名皆源于此。它确立了大一统王朝的基本范式，垂范后世两千年。其“独尊儒术”与郡县、察举相配，构造出长效的政教机制。""",
    "lishi-tang": """唐都长安为当时世界最大都会，胡汉交融、释道并隆。科举取士打破门第，诗歌气象恢宏，贞观开元之治为史家称颂。其开放包容的文明格局，使唐成为华夏盛世的符号，海外至今以“唐人”称华人。其以诗赋取士，遂使诗歌化民俗、胡梵融会成盛唐之音。""",
    "lishi-song": """宋重文抑武，文官政治臻于成熟，活字、指南、火药之术渐兴。理学昌明，程朱奠定道统；市井经济与海外贸易繁盛，纸币交子问世。虽边患不绝，其文化高度与经济活力却为后世艳称，有“华夏文化造极于赵宋”之评。然“与士大夫治天下”亦埋边备空虚之患。""",
    "lishi-yuan": """元由蒙古建立，首次由异族一统天下，行行省制以控地方，开通京杭运河贯通南北。中西交通因欧亚草原之路大畅，马可·波罗之记西传。其四等人制虽存歧视，却也促成了多民族版图与宗教的空前交汇。其行省之制，明继而损益，今“省”实滥觞于此。""",
    "lishi-ming": """明废丞相、权归六部，设内阁以备顾问，皇权空前集中。郑和七下西洋彰显国威，中叶后市舶与民营渐兴。阳明心学振起，小说戏曲勃发。然北虏南倭、宦官迭乱，终以内忧外患交困，为清所代。其海禁与朝贡之矛盾，折射出面对海洋时的犹疑，令人扼腕。""",
    "lishi-qing": """清入关后承明制而有所损益，康雍乾百年励精，编《四库》、定疆域，版图奠定今日中国之雏形。然闭关与专制日甚，遇三千年未有之变局而应变维艰。它的盛衰，恰是传统帝国面对近代世界冲击的一部缩影。其“满汉一体”与边疆经营，使多民族整合达于空前。""",
    "lishi-sansheng": """华夏向以“三圣”追慕文明初创之功，或言伏羲画卦、神农尝草、黄帝垂衣，或尊尧舜禹禅让授受。这些半传说半信史的人物，凝结了先民对秩序、农耕与德治的最早想象，奠定了民族共同记忆的起点。后世祠祀不绝、追谥加封，已超越史实而成文化符号。""",
    "lishi-keju": """科举始于隋、备于唐、盛于宋，以诗赋经义取士，打破了门阀对官场的垄断。它使“朝为田舍郎，暮登天子堂”成为可能，寒俊得以凭才学致身通显，亦令儒家经典深入民间，维系了帝国与士人间的长久纽带。然八股渐成桎梏，晚清废科举兴学校，公平精神仍存于今之考试。""",
    "lishi-jiancha": """自秦汉御史之制，至唐分台、谏，明清都察院与六科给事中并行，监察之网渐密。言官风闻奏事，纠官邪、肃纲纪，虽常沦为党争之具，却也构成制衡皇权与吏治腐败的一道制度防线，为后世所沿袭。包拯、海瑞辈赖此伸志，然其效终系于君明法立。""",
    "lishi-fenjun": """分封起于夏商、盛于周，以宗法血缘裂土授亲，屏卫王室。然诸侯力政终致春秋之乱。秦废封建行郡县，开中央集权之端；汉初郡国并行、七国生变，此后历代多在封建与郡县间权衡，柳宗元《封建论》即就此而发。顾炎武倡“寓封建于郡县”，其思犹有回响。""",
    "lishi-zaixiang": """宰相为百官之首，佐天子理万机。汉以丞相开府，唐行三省、宋设同平章事，明太祖借胡案废相、以内阁替之，相权一落千丈。这一由盛而衰的演变，实为皇权不断收拢、专制日趋强化的清晰缩影。张九龄、王安石诸相之进退，皆随皇权张弛而浮沉。""",
    "lishi-ganzhi": """天干地支各十与十二，相配成六十甲子循环，用以纪年、月、日、时，相传自上古黄帝历始。它不依赖数字进位，而与节气、生肖相系，深入农事与民俗。今日春联、生辰、纪年仍见其影，是华夏时间观的独特印记。它更渗入命理与中医运气，成理解节律的底层编码。""",
    "lishi-sichou": """丝绸为华夏献给世界的珍物，自先秦已精。汉通西域，商旅驼队载锦绮西去，远抵罗马，遂有“丝绸之路”之名。丝不仅换回良马异货，更传去了养蚕、织造之术，成为早期中外文明对话最柔韧的纽带。敦煌残卷与楼兰故锦，至今犹见其华彩，丝路对话从未止息。""",
    "lishi-sida": """造纸、印刷、火药、指南针被誉四大发明，经阿拉伯西传，深刻改写了世界进程：纸与印刷助欧洲文艺复兴，火药崩塌骑士堡垒，罗盘开启大航海。培根虽未明言其源，却已叹服此三端“已在世上引起无穷变革”。鲁迅亦曾以此叹技术与社会之联，促人深思。""",
    "lishi-changcheng": """长城非一朝之功，战国诸侯已各筑以备胡，秦连而为一，汉、明续筑。它不是一道孤墙，而是烽燧、关城、屯田相维的防御体系。虽未能尽阻铁骑，却成为农耕与游牧长期拉锯的界标，亦化作民族精神的象征。今日砖石虽损，登临者仍可想见戍卒望乡之思。""",
    "lishi-zhenghe": """郑和自永乐三年起七下西洋，率宝船二百余艘远抵非洲东岸，宣扬国威、通好三十余国。其船阵之巨、航技之精冠绝当时，却因耗帑过巨、海禁复行而中辍。这场和平远航的戛然而止，至今令人叹惋。其行比哥伦布早逾半世纪，和平姿态与后世殖民扩张形成耐人对照。""",
    "lishi-weijin": """魏晋之际，士处乱朝，乃尚清谈、任自然，以狂狷避祸。竹林七贤越礼放达，书法绘画由质转文，建安风骨余韵未歇。门阀政治与玄学思潮交织，造就了既颓唐又风流的一代气象，深远影响了文人人格范式。王羲之《兰亭》之雅、渊明归田之逸，皆萌于此际。""",
    "lishi-chunqiu": """春秋二百余载，王室衰微、诸侯争霸，齐桓晋文相继主盟，礼崩乐坏而思想竞发，遂有诸子勃兴。孔子因鲁史作《春秋》，以褒贬寄微言大义。这一段“礼乐征伐自诸侯出”的转型，实为华夏从封建走向更大一统的序幕。《左传》叙事之工，使分裂时代成散文与辞令黄金期。""",
    "lishi-xiashangzhou": """夏商周三代递嬗，由部落联盟渐入王国。商有甲骨卜辞可证信史，周制礼乐、行封建、重宗法，奠定华夏族群与政教之基。三代虽多赖传说，却是“中国”认同与文字、礼制连续性的最早源头。周公制礼作乐，更将血缘伦理升为国家制度，其泽被后世极深。""",
    "lishi-nanbeichao": """永嘉南渡，晋室偏安，南北对峙近三百年。北朝胡汉杂糅、均田府兵，南朝文采风流、清谈未已；佛教于此大盛，石窟造像辉映山河。分裂之中，民族交融与制度嬗变悄然进行，为隋唐一统蓄势。《木兰辞》与《世说新语》并出此时，分裂反倒孕育丰盈文学生命。""",
    "lishi-wudai": """五代五十三年间，中原五朝更易、藩镇割据，武人跋扈、生民涂炭，史称“天地闭、贤人隐”。然南方诸国保境安民，经济文化反得喘息；词艺于离乱中愈工，印刷、航运渐兴，乱世亦藏承启之机。《花间集》香软、李后主词沉痛，短祚政权掩不住文化暗流涌动。""",
    "lishi-liaojinxixia": """辽、金、西夏鼎立于宋之北疆，皆仿汉制而立国：辽分南北面官以治胡汉，金行科举、创女真文，西夏兼用番汉、崇佛译经。它们与宋的战和，织就了多政权并存的复杂图景，丰富了中华一体多元的格局。其钱币文书今犹可考，多语并存正是“多元一体”的史证。""",
}
